  def self.config
    return @config if @config
    @config = DEFAULTS.clone
    if File.exist?(CONFIG_FILE)
      File.readlines(CONFIG_FILE).each do |line|
        line = line.strip
        next if line.empty? || line[0,1] == "#" || !line.include?("=")
        key, value = line.split("=", 2)
        @config[key.strip.downcase] = value.strip
      end
    end
    @config
  end

  def self.enabled?(key)
    value = config[key].to_s.downcase
    value == "true" || value == "1" || value == "yes" || value == "on"
  end

  def self.seed
    config["seed"].to_i
  end

  def self.hash_value(text)
    h = seed & 0x7fffffff
    text.to_s.each_byte do |b|
      h = ((h * 1103515245) + b + 12345) & 0x7fffffff
    end
    h
  end

  def self.pick(pool, key)
    return nil if pool.nil? || pool.empty?
    pool[hash_value(key) % pool.length]
  end

  def self.map_id(interpreter)
    interpreter.instance_variable_get(:@map_id).to_i
  end

  def self.intro_map?(interpreter)
    INTRO_MAP_IDS.include?(map_id(interpreter))
  end

  def self.protected_bloody_key?(interpreter, params)
    map_id(interpreter) == CRASH_CHAMBER_MAP_ID && params && params[0].to_i == BLOODY_KEY_ITEM_ID
  end

  def self.location_key(kind, interpreter)
    map_id = interpreter.instance_variable_get(:@map_id).to_i
    event_id = interpreter.instance_variable_get(:@event_id).to_i
    index = interpreter.instance_variable_get(:@index).to_i
    kind.to_s + ":" + map_id.to_s + ":" + event_id.to_s + ":" + index.to_s
  end

  def self.transfer_key(interpreter, params)
    map_id = interpreter.instance_variable_get(:@map_id).to_i
    event_id = interpreter.instance_variable_get(:@event_id).to_i
    index = interpreter.instance_variable_get(:@index).to_i
    [map_id,event_id,index,params[1].to_i,params[2].to_i,params[3].to_i].join(":")
  end

  def self.troop_pool
    return @troop_pool if @troop_pool
    @troop_pool = []
    if $data_troops
      $data_troops.each_with_index do |troop, id|
        next if id == 0 || troop.nil?
        members = troop.respond_to?(:members) ? troop.members : []
        next if members.nil? || members.empty?
        @troop_pool << id
      end
    end
    @troop_pool
  end

  def self.valid_named_object?(obj)
    return false if obj.nil?
    name = obj.respond_to?(:name) ? obj.name.to_s : ""
    !name.strip.empty?
  end

  # White Crow and similar exchange shops use EasyCompose recipes (Candies)
  # stored on the ORIGINAL database item, not the normal VX Ace price field.
  # When an item is shuffled into a shop slot, retain that slot's original
  # recipe so the replacement costs exactly the same Candies.
  def self.clear_shop_recipe_overrides
    @shop_recipe_overrides = {}
  end

  def self.shop_object_key(obj)
    return nil if obj.nil? || !obj.respond_to?(:id)
    [obj.class.to_s, obj.id.to_i]
  end

  def self.copy_compose_recipe(recipe)
    result = {}
    return result unless recipe
    recipe.each do |kind, entries|
      result[kind] = {}
      entries.each { |id, count| result[kind][id] = count } if entries
    end
    result
  end

  def self.register_shop_recipe_override(obj, recipe)
    key = shop_object_key(obj)
    return unless key
    @shop_recipe_overrides ||= {}
    @shop_recipe_overrides[key] = copy_compose_recipe(recipe)
  end

  def self.shop_recipe_override(obj)
    return nil unless defined?(EasyCompose)
    return nil unless $game_switches && $game_switches[EasyCompose::SID]
    @shop_recipe_overrides ||= {}
    @shop_recipe_overrides[shop_object_key(obj)]
  end

  def self.database_pool(data, kind = nil)
    result = []
    return result if data.nil?
    data.each_with_index do |obj, id|
      next if id == 0 || !valid_named_object?(obj)
      next if kind.to_s == "item" && never_shuffle_item?(id)
      result << id
    end
    result
  end

  # Sattolo cycle: deterministic permutation with no fixed points where a pool
  # has at least two entries.
  def self.permutation_for_ids(ids, cache_key)
    @permutation_maps ||= {}
    return @permutation_maps[cache_key] if @permutation_maps[cache_key]
    ids = ids.uniq.clone
    result = {}
    if ids.length == 1
      result[ids[0]] = ids[0]
    elsif ids.length > 1
      shuffled = ids.clone
      state = hash_value("perm:" + cache_key.to_s) & 0x7fffffff
      i = shuffled.length - 1
      while i > 0
        state = (state * 1103515245 + 12345) & 0x7fffffff
        j = state % i
        tmp = shuffled[i]; shuffled[i] = shuffled[j]; shuffled[j] = tmp
        i -= 1
      end
      ids.each_with_index { |id, idx| result[id] = shuffled[idx] }
    end
    @permutation_maps[cache_key] = result
  end

  def self.permutation_map(data, kind)
    ids = database_pool(data, kind)
    permutation_for_ids(ids, "global:" + kind.to_s)
  end

  def self.region_pool(kind, map_id)
    region = region_for_map(map_id)
    case kind.to_s
    when "troop" then REGION_TROOP_POOLS[region] || []
    when "item" then REGION_ITEM_POOLS[region] || []
    when "weapon" then REGION_WEAPON_POOLS[region] || []
    when "armor" then REGION_ARMOR_POOLS[region] || []
    else []
    end
  end

  def self.shuffled_item_id(original_id, kind, data, map_id = nil)
    return nil if data.nil? || original_id <= 0 || original_id >= data.length
    original = data[original_id]
    return nil unless valid_named_object?(original)
    # Drink Me and Eat Me are progression mechanics and are never transformed.
    return original_id if kind.to_s == "item" && never_shuffle_item?(original_id)

    if regional_mode? && map_id
      ids = (region_pool(kind, map_id) + shop_extra_pool(kind, map_id)).uniq.select do |id|
        id > 0 && id < data.length && valid_named_object?(data[id]) &&
          !(kind.to_s == "item" && never_shuffle_item?(id))
      end
      return original_id unless ids.include?(original_id)
      permutation_for_ids(ids, "region:" + region_for_map(map_id).to_s + ":" + kind.to_s)[original_id] || original_id
    else
      permutation_map(data, kind)[original_id] || original_id
    end
  end

  def self.random_troop(interpreter)
    mid = map_id(interpreter)
    params = interpreter.instance_variable_get(:@params) || []
    original_id = 0
    if params[0].to_i == 0
      original_id = params[1].to_i
    elsif params[0].to_i == 1 && defined?($game_variables) && $game_variables
      original_id = $game_variables[params[1].to_i].to_i
    end

    if regional_mode?
      ids = region_pool("troop", mid).select { |id| troop_pool.include?(id) }
      return original_id if original_id > 0 && !ids.include?(original_id)
      return nil if ids.empty? || original_id <= 0
      permutation_for_ids(ids, "region:" + region_for_map(mid).to_s + ":troop")[original_id] || original_id
    else
      pick(troop_pool, location_key("enemy", interpreter))
    end
  end

  # Physical door groups are rebuilt from DOOR_ENDPOINTS at runtime in v0.7.
  # This replaces the old precomputed grouping that could split long entrances.

  # Build physical doorway sides from the raw reversible transfer endpoints.
  # v0.7 uses a true flood fill with no length limit, so a 5-, 10-, or 20-tile
  # contiguous entrance is still treated as one doorway.
  def self.physical_door_groups
    return @physical_door_groups if @physical_door_groups
    buckets = {}
    DOOR_ENDPOINTS.each do |ep|
      parts = ep[0].split(":")
      dest_map = parts[3].to_i
      bucket_key = [ep[1].to_i, dest_map, ep[4].to_i, ep[5].to_i]
      buckets[bucket_key] ||= []
      buckets[bucket_key] << ep
    end
    groups = []
    buckets.each do |bucket_key, endpoints|
      unused = endpoints.clone
      until unused.empty?
        seed_ep = unused.shift
        component = [seed_ep]
        changed = true
        while changed
          changed = false
          unused.clone.each do |ep|
            touching = component.any? do |other|
              dx = (ep[2].to_i - other[2].to_i).abs
              dy = (ep[3].to_i - other[3].to_i).abs
              (dx + dy) <= 1
            end
            if touching
              component << ep
              unused.delete(ep)
              changed = true
            end
          end
        end
        xs = component.map { |e| e[2].to_i }.sort
        ys = component.map { |e| e[3].to_i }.sort
        groups << {
          :keys => component.map { |e| e[0] }.uniq,
          :map => bucket_key[0], :dest_map => bucket_key[1],
          :x => xs[xs.length / 2], :y => ys[ys.length / 2],
          :direction => bucket_key[2], :fade => bucket_key[3],
          :pair_ids => component.map { |e| e[6].to_i }.uniq
        }
      end
    end
    @physical_door_groups = groups
  end

  # Match each physical side to its original reverse side using verified pair IDs.
  # Ambiguous sides are left vanilla rather than guessed.
  def self.reversible_group_pairs
    return @reversible_group_pairs if @reversible_group_pairs
    groups = physical_door_groups
    by_pair = {}
    groups.each_with_index do |g, gi|
      g[:pair_ids].each do |pid|
        by_pair[pid] ||= []
        by_pair[pid] << gi
      end
    end
    scores = Hash.new { |h,k| h[k] = Hash.new(0) }
    by_pair.each_value do |ids|
      ids = ids.uniq
      next unless ids.length == 2
      a,b = ids
      scores[a][b] += 1; scores[b][a] += 1
    end
    best = {}
    scores.each do |a, choices|
      ordered = choices.to_a.sort_by { |pair| [-pair[1], pair[0]] }
      next if ordered.empty?
      next if ordered.length > 1 && ordered[0][1] == ordered[1][1]
      best[a] = ordered[0][0]
    end
    pairs = []; used = {}
    best.each do |a,b|
      next unless best[b] == a
      next if used[a] || used[b]
      ga,gb = groups[a],groups[b]
      next unless ga[:map] == gb[:dest_map] && gb[:map] == ga[:dest_map]
      pairs << [a,b]; used[a] = used[b] = true
    end
    @reversible_group_pairs = pairs
  end

  def self.eligible_group_ids(regional)
    groups = physical_door_groups
    ids = []
    reversible_group_pairs.each do |a,b|
      if regional
        next unless region_for_map(groups[a][:map]) == region_for_map(groups[b][:map])
      end
      ids << a << b
    end
    ids.uniq
  end

  def self.shuffle_array(array, key)
    a = array.clone
    state = hash_value(key) & 0x7fffffff
    i = a.length - 1
    while i > 0
      state = (state * 1103515245 + 12345) & 0x7fffffff
      j = state % (i + 1)
      a[i], a[j] = a[j], a[i]
      i -= 1
    end
    a
  end

  def self.pairing_for_ids(ids, key)
    shuffled = shuffle_array(ids, key)
    pairs = []; i = 0
    while i + 1 < shuffled.length
      pairs << [shuffled[i], shuffled[i+1]]
      i += 2
    end
    pairs
  end

  def self.original_pairs_for_ids(ids)
    allowed = {}; ids.each { |id| allowed[id] = true }
    reversible_group_pairs.select { |a,b| allowed[a] && allowed[b] }
  end

  # Conservatively remove the vanilla map-to-map edge for each doorway that is
  # being shuffled. If another unshuffled transfer happens to share that edge,
  # omitting it here only makes Safety stricter, never less safe.
  def self.fixed_edges_for(regional)
    edges = {}; ALL_TRANSFER_EDGES.each { |m,ds| edges[m] = ds.clone }
    groups = physical_door_groups
    reversible_group_pairs.each do |a,b|
      if regional
        next unless region_for_map(groups[a][:map]) == region_for_map(groups[b][:map])
      end
      [[a,b],[b,a]].each do |x,y|
        src = groups[x][:map]; dst = groups[y][:map]
        edges[src] = (edges[src] || []).reject { |v| v.to_i == dst.to_i }
      end
    end
    edges
  end

  def self.edges_with_pairs(regional, pairs)
    edges = fixed_edges_for(regional)
    groups = physical_door_groups
    pairs.each do |a,b|
      ma,mb = groups[a][:map],groups[b][:map]
      edges[ma] ||= []; edges[mb] ||= []
      edges[ma] << mb unless edges[ma].include?(mb)
      edges[mb] << ma unless edges[mb].include?(ma)
    end
    edges
  end

  def self.reachable_maps(edges, start_map)
    seen = { start_map.to_i => true }; queue = [start_map.to_i]
    until queue.empty?
      m = queue.shift
      (edges[m] || []).each do |dst|
        dst = dst.to_i
        next if seen[dst]
        seen[dst] = true; queue << dst
      end
    end
    seen
  end

  def self.safe_pairs?(regional, pairs)
    seen = reachable_maps(edges_with_pairs(regional, pairs), CRASH_CHAMBER_MAP_ID)
    VANILLA_REACHABLE_MAPS.all? { |m| seen[m.to_i] }
  end

  # Safety v0.8: start from the known-safe vanilla reversible pairing, then
  # repeatedly perform deterministic two-edge swaps. A swap is accepted only
  # if every map that was reachable from Crash Chamber in the vanilla static
  # transfer graph is still reachable afterward. This guarantees that Safety
  # produces an actual shuffle instead of trying random full layouts and then
  # falling back to vanilla when none happen to pass.
  #
  # Reachability is intentionally one-way: a room only needs a path INTO it.
  # It does not need a path back out, because the player can use the starting
  # teleport item / bonfire network to return to safety. Crash Chamber's two
  # event-state variants share map ID 1, so they are naturally treated as the
  # same traversal anchor by this map-level graph.
  def self.safe_shuffled_pairs(regional)
    groups = physical_door_groups
    ids = eligible_group_ids(regional)
    pairs = original_pairs_for_ids(ids)
    return pairs if pairs.length < 2

    # Only swap pairs that belong to the same region in regional mode.
    pair_buckets = {}
    pairs.each_with_index do |pair, idx|
      if regional
        r = region_for_map(groups[pair[0]][:map])
        pair_buckets[r] ||= []
        pair_buckets[r] << idx
      else
        pair_buckets[0] ||= []
        pair_buckets[0] << idx
      end
    end

    state = hash_value(regional ? "safe_swap_regional" : "safe_swap_global") & 0x7fffffff
    attempts_per_pair = 36
    total_attempts = [pairs.length * attempts_per_pair, 300].max

    total_attempts.times do
      buckets = pair_buckets.keys.select { |k| pair_buckets[k].length >= 2 }
      break if buckets.empty?
      state = (state * 1103515245 + 12345) & 0x7fffffff
      bucket = buckets[state % buckets.length]
      indices = pair_buckets[bucket]

      state = (state * 1103515245 + 12345) & 0x7fffffff
      i = indices[state % indices.length]
      state = (state * 1103515245 + 12345) & 0x7fffffff
      j = indices[state % indices.length]
      next if i == j

      a,b = pairs[i]
      c,d = pairs[j]
      # Alternate the cross-wiring orientation deterministically.
      state = (state * 1103515245 + 12345) & 0x7fffffff
      if (state & 1) == 0
        p1 = [a,c]; p2 = [b,d]
      else
        p1 = [a,d]; p2 = [b,c]
      end
      next if p1[0] == p1[1] || p2[0] == p2[1]

      candidate = pairs.clone
      candidate[i] = p1
      candidate[j] = p2
      if safe_pairs?(regional, candidate)
        pairs = candidate
      end
    end

    pairs
  end

  def self.build_pairs(regional)
    groups = physical_door_groups
    if regional
      if enabled?("safety")
        return safe_shuffled_pairs(true)
      end
      by_region = {}
      eligible_group_ids(true).each do |id|
        r = region_for_map(groups[id][:map]); by_region[r] ||= []; by_region[r] << id
      end
      pairs = []
      by_region.keys.sort.each do |r|
        pairs.concat(pairing_for_ids(by_region[r], "door_region:#{r}"))
      end
      pairs
    else
      ids = eligible_group_ids(false)
      return safe_shuffled_pairs(false) if enabled?("safety")
      pairing_for_ids(ids, "door_global")
    end
  end

  def self.door_map
    return @door_map if @door_map
    @door_map = {}; groups = physical_door_groups
    build_pairs(regional_mode?).each do |a,b|
      ga,gb = groups[a],groups[b]
      dest_b = [gb[:map], gb[:x], gb[:y], gb[:direction], gb[:fade]]
      dest_a = [ga[:map], ga[:x], ga[:y], ga[:direction], ga[:fade]]
      ga[:keys].each { |key| @door_map[key] = dest_b }
      gb[:keys].each { |key| @door_map[key] = dest_a }
    end
    @door_map
  end

  def self.shuffled_destination(interpreter, params)
    door_map[transfer_key(interpreter, params)]
  end

end

class Game_Interpreter
  alias bs2r4_command_201 command_201
  alias bs2r4_command_301 command_301
  alias bs2r4_command_126 command_126
  alias bs2r4_command_127 command_127
  alias bs2r4_command_128 command_128

  def command_201
    if !BS2Randomizer.intro_map?(self) && BS2Randomizer.enabled?("room_transition_randomization") && @params[0] == 0
      destination = BS2Randomizer.shuffled_destination(self, @params)
      if destination
        original = @params
        @params = [0, destination[0], destination[1], destination[2], destination[3], destination[4]]
        begin
          return bs2r4_command_201
        ensure
          @params = original
        end
      end
    end
    bs2r4_command_201
  end

  def command_301
    if !BS2Randomizer.intro_map?(self) && BS2Randomizer.enabled?("enemy_randomization")
      troop_id = BS2Randomizer.random_troop(self)
      if troop_id
        original = @params
        @params = [0, troop_id, @params[2], @params[3]]
        begin
          return bs2r4_command_301
        ensure
          @params = original
        end
      end
    end
    bs2r4_command_301
  end

  def command_126
    if !BS2Randomizer.intro_map?(self) && !BS2Randomizer.protected_bloody_key?(self, @params) && !BS2Randomizer.never_shuffle_item?(@params[0]) && BS2Randomizer.enabled?("item_randomization")
      value = operate_value(@params[1], @params[2], @params[3])
      if value > 0
        id = BS2Randomizer.shuffled_item_id(@params[0].to_i, "item", $data_items, BS2Randomizer.map_id(self))
        if id
          original = @params
          @params = [id, @params[1], @params[2], @params[3]]
          begin
            return bs2r4_command_126
          ensure
            @params = original
          end
        end
      end
    end
    bs2r4_command_126
  end

  def command_127
    if !BS2Randomizer.intro_map?(self) && BS2Randomizer.enabled?("item_randomization")
      value = operate_value(@params[1], @params[2], @params[3])
      if value > 0
        id = BS2Randomizer.shuffled_item_id(@params[0].to_i, "weapon", $data_weapons, BS2Randomizer.map_id(self))
        if id
          original = @params
          @params = [id, @params[1], @params[2], @params[3], @params[4]]
          begin
            return bs2r4_command_127
          ensure
            @params = original
          end
        end
      end
    end
    bs2r4_command_127
  end

  def command_128
    if !BS2Randomizer.intro_map?(self) && BS2Randomizer.enabled?("item_randomization")
      value = operate_value(@params[1], @params[2], @params[3])
      if value > 0
        id = BS2Randomizer.shuffled_item_id(@params[0].to_i, "armor", $data_armors, BS2Randomizer.map_id(self))
        if id
          original = @params
          @params = [id, @params[1], @params[2], @params[3], @params[4]]
          begin
            return bs2r4_command_128
          ensure
            @params = original
          end
        end
      end
    end
    bs2r4_command_128
  end
end


# Shop goods use the same seeded item/equipment mapping as scripted rewards.
# Scene_Shop#prepare receives goods as [type, id, price_type, price].
class Scene_Shop < Scene_MenuBase
  alias bs2r5_prepare prepare

  def prepare(goods, purchase_only)
    BS2Randomizer.clear_shop_recipe_overrides
    if BS2Randomizer.enabled?("item_randomization")
      mid = $game_map ? $game_map.map_id.to_i : 0
      shuffled_goods = goods.map do |good|
        g = good.clone
        kind = nil
        data = nil
        case g[0].to_i
        when 0 then kind = "item"; data = $data_items
        when 1 then kind = "weapon"; data = $data_weapons
        when 2 then kind = "armor"; data = $data_armors
        end
        if kind && data
          original_id = g[1].to_i
          original_entry = data[original_id] rescue nil
          original_price = if g[2].to_i == 0
            original_entry && original_entry.respond_to?(:price) ? original_entry.price.to_i : 0
          else
            g[3].to_i
          end
          id = BS2Randomizer.shuffled_item_id(original_id, kind, data, mid)
          if id
            replacement_entry = data[id] rescue nil
            if defined?(EasyCompose) && $game_switches && $game_switches[EasyCompose::SID]
              if original_entry && original_entry.respond_to?(:easy_compose_item_list) && replacement_entry
                BS2Randomizer.register_shop_recipe_override(replacement_entry, original_entry.easy_compose_item_list)
              end
            end
            g[1] = id
            # Pricing differs by shop type.
            #
            # EasyCompose / White Crow exchange shops use Candy recipes, so
            # keep the original slot's normal price metadata as before while
            # the recipe override above preserves the original Candy cost.
            #
            # Normal Soul shops price a randomized replacement at THREE TIMES
            # that replacement item's in-game sell value.  Black Souls II uses
            # VX Ace's standard sell formula (@item.price / 2).  If the
            # replacement has no sell value (0), preserve the original slot's
            # effective Soul price instead.
            is_compose_shop = defined?(EasyCompose) && $game_switches && $game_switches[EasyCompose::SID]
            if is_compose_shop
              new_price = original_price
            else
              sell_value = replacement_entry && replacement_entry.respond_to?(:price) ? replacement_entry.price.to_i / 2 : 0
              new_price = sell_value > 0 ? sell_value * 3 : original_price
            end
            g[2] = 1
            g[3] = new_price
          end
        end
        g
      end
      return bs2r5_prepare(shuffled_goods, purchase_only)
    end
    bs2r5_prepare(goods, purchase_only)
  end
end


# EasyCompose (used by White Crow) normally reads Candy requirements from the
# currently displayed item's note tags.  During a randomized exchange shop,
# substitute the ORIGINAL shop slot's recipe instead.
if defined?(EasyCompose) && RPG::BaseItem.method_defined?(:easy_compose_item_list)
  class RPG::BaseItem
    alias bs2r52_easy_compose_item_list easy_compose_item_list
    def easy_compose_item_list
      recipe = BS2Randomizer.shop_recipe_override(self)
      return recipe if recipe
      bs2r52_easy_compose_item_list
    end
  end
end
